// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

import "./reactive-lib/interfaces/IReactive.sol";
import "./reactive-lib/abstract-base/AbstractReactive.sol";
import "./reactive-lib/interfaces/ISystemContract.sol";

/**
 * @title InflowDCAReactive
 * @notice Deployed on Lasna testnet. Subscribes to ERC-20 Transfer events where recipient == vault
 *         and fires an authenticated callback to executeInflowDCA on destination vault.
 */
contract InflowDCAReactive is IReactive, AbstractReactive {
    uint256 public originChainId;
    uint256 public destinationChainId;
    address public originToken;       // Inflow ERC-20 token (e.g. USDC)
    address public originVault;       // Monitored Vault receiving the transfer
    address public destinationVault;  // Target Vault executing the callback swap
    uint256 public minInflowThreshold;// Anti-spam threshold to protect Lasna gas balance
    uint64 private constant GAS_LIMIT = 1000000;

    // keccak256("Transfer(address,address,uint256)")
    uint256 public constant ERC20_TRANSFER_TOPIC_0 = 
        uint256(keccak256("Transfer(address,address,uint256)"));

    event DCAProcessed(uint256 indexed amount, address indexed vault);

    constructor(
        uint256 _originChainId,
        uint256 _destinationChainId,
        address _originToken,
        address _originVault,
        address _destinationVault,
        uint256 _minInflowThreshold
    ) payable {
        originChainId = _originChainId;
        destinationChainId = _destinationChainId;
        originToken = _originToken;
        originVault = _originVault;
        destinationVault = _destinationVault;
        minInflowThreshold = _minInflowThreshold;

        if (!vm) {
            // Subscribe to Transfer(from, to, amount) events emitted by originToken
            // topic_0: Transfer signature
            // topic_1: from (REACTIVE_IGNORE matches any sender)
            // topic_2: to (filtered specifically to originVault)
            // topic_3: REACTIVE_IGNORE
            service.subscribe(
                originChainId,
                originToken,
                ERC20_TRANSFER_TOPIC_0,
                REACTIVE_IGNORE,
                uint256(uint160(originVault)), // indexed 'to' address as topic_2
                REACTIVE_IGNORE
            );
        }
    }

    /**
     * @notice Invoked by ReactVM when an event matching subscription is detected.
     */
    function react(LogRecord calldata log) external vmOnly {
        // Double check token contract, topic_0, and destination topic_2
        if (
            log._contract != originToken ||
            log.topic_0 != ERC20_TRANSFER_TOPIC_0 ||
            log.topic_2 != uint256(uint160(originVault))
        ) {
            return;
        }

        // In standard ERC20 Transfer(from, to, amount):
        // amount is non-indexed and passed in log.data (32 bytes)
        uint256 amount = abi.decode(log.data, (uint256));

        // Anti-spam guard: ignore dust transfers below threshold
        if (amount >= minInflowThreshold) {
            // Encode callback to destination vault: executeInflowDCA(address sender, uint256 inflowAmount)
            // Note: address(0) placeholder is replaced with this reactive contract's RVM address by Reactive relayer
            bytes memory payload = abi.encodeWithSignature(
                "executeInflowDCA(address,uint256)",
                address(0),
                amount
            );

            emit Callback(destinationChainId, destinationVault, GAS_LIMIT, payload);
            emit DCAProcessed(amount, destinationVault);
        }
    }
}

contracts/InflowVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./reactive-lib/abstract-base/AbstractCallback.sol";

interface IMockDEX {
    function swap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        address recipient
    ) external returns (uint256 amountOut);
}

/**
 * @title InflowVault
 * @notice Holds user funds, allows direct ERC-20 transfers or deposit calls,
 *         and executes swaps upon verified Reactive callbacks from Lasna.
 */
contract InflowVault is AbstractCallback {
    using SafeERC20 for IERC20;

    address public owner;
    address public dexRouter;
    address public inputToken;       // e.g. USDC (inflow token)
    address public outputToken;      // e.g. WETH (accumulated asset)
    uint256 public dcaPercentageBps; // basis points (e.g., 5000 = 50%, 10000 = 100%)

    event InflowReceived(
        address indexed sender,
        address indexed token,
        uint256 amount,
        uint256 timestamp
    );

    event DCASwapped(
        address indexed caller,
        uint256 amountIn,
        uint256 amountOut,
        uint256 timestamp
    );

    event RvmIdUpdated(address indexed oldRvmId, address indexed newRvmId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor(
        address _callbackSender,
        address _dexRouter,
        address _inputToken,
        address _outputToken,
        uint256 _dcaPercentageBps
    ) AbstractCallback(_callbackSender) payable {
        owner = msg.sender;
        dexRouter = _dexRouter;
        inputToken = _inputToken;
        outputToken = _outputToken;
        dcaPercentageBps = _dcaPercentageBps;
    }

    /**
     * @notice Allows owner to update authorized Reactive contract address (RVM ID).
     *         Critical for post-deployment handshake after deploying on Lasna testnet.
     */
    function setRvmId(address _newRvmId) external onlyOwner {
        require(_newRvmId != address(0), "Invalid RVM ID");
        emit RvmIdUpdated(rvm_id, _newRvmId);
        rvm_id = _newRvmId;
    }

    /**
     * @notice Deposit helper for UI and tests. Standard ERC-20 transfers directly to this address
     *         are also caught by the Reactive contract via ERC-20 Transfer event subscription.
     */
    function deposit(uint256 amount) external {
        require(amount > 0, "Zero deposit");
        IERC20(inputToken).safeTransferFrom(msg.sender, address(this), amount);
        emit InflowReceived(msg.sender, inputToken, amount, block.timestamp);
    }

    /**
     * @notice Callback invoked by Reactive Network relayer upon catching an inflow event.
     * @param sender The address of the authorized reactive contract (RVM ID).
     * @param inflowAmount The amount of token received in the detected inflow.
     */
    function executeInflowDCA(address sender, uint256 inflowAmount)
        external
        authorizedSenderOnly
        rvmIdOnly(sender)
    {
        uint256 balance = IERC20(inputToken).balanceOf(address(this));
        if (balance == 0 || inflowAmount == 0) return;

        // Calculate amount to swap based on inflow and configured percentage
        uint256 swapAmount = (inflowAmount * dcaPercentageBps) / 10000;
        if (swapAmount > balance) {
            swapAmount = balance;
        }

        if (swapAmount > 0) {
            IERC20(inputToken).forceApprove(dexRouter, swapAmount);
            uint256 amountOut = IMockDEX(dexRouter).swap(
                inputToken,
                outputToken,
                swapAmount,
                address(this)
            );

            emit DCASwapped(sender, swapAmount, amountOut, block.timestamp);
        }
    }

    function setConfig(
        address _dexRouter,
        address _inputToken,
        address _outputToken,
        uint256 _dcaPercentageBps
    ) external onlyOwner {
        dexRouter = _dexRouter;
        inputToken = _inputToken;
        outputToken = _outputToken;
        dcaPercentageBps = _dcaPercentageBps;
    }

    function withdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(owner, amount);
    }

    function getRvmId() external view returns (address) {
        return rvm_id;
    }
}

